            .short("s")
            .long("save")
            .help("Set the output file to the path of the input file"))
        .arg(Arg::with_name("version")
            .short("V")
            .long("version")
            .help("Prints version information"))
        .arg(Arg::with_name("config")
            .short("c")
            .long("config")
            .value_name("file")
            .help("The config file the theme should be applied to. Defaults to the default i3 location.")
            .takes_value(true))
        .arg(Arg::with_name("output")
            .short("o")
            .long("output")
            .value_name("file")
            .help("Apply the theme, attempt to validate the result, and write it to <file>")
            .takes_value(true))
        .arg(Arg::with_name("to-theme")
            .short("t")
            .long("to-theme")
            .value_name("file")
            .help("Prints an i3-style theme based on the given config suitable for sharing with others")
            .takes_value(true)
            .default_value(""))
        .arg(Arg::with_name("theme")
            .help("The theme to use")
            .required(false)
            .index(1))
        .get_matches();

    // Handle help and version manually to match original?
    // clap will handle -h and --help and -V automatically, but we need to ensure behavior matches.
