        if let Some(ind) = indicator_opt {
            let ind_name = get_name(ind, &mut colors, &mut name_counter);
            let wc = WindowColors {
                border: border_name,
                background: bg_name,
                text: text_name,
                indicator: ind_name,
            };
            window_colors.insert(cls.to_string(), wc);
        } else {
            let wc = WindowColors {
                border: border_name,
                background: bg_name,
                text: text_name,
                indicator: String::new(),
