        panic!("called `Result::unwrap()` on an `Err` value: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
    });

    let final_output = if let Some(o) = output_path.clone() {
        Some(o)
    } else if save {
        Some(resolved_config.clone())
    } else {
        None
    };

    let themed = writer::apply_theme_to_config(&config_content, &theme_data);

    let timestamp = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs();
    let tmp_dir = format!("/tmp/i3-style/{}", timestamp);
    let _ = fs::create_dir_all(&tmp_dir);
    let tmp_input = format!("{}/config-input", tmp_dir);
    let tmp_output = format!("{}/config-output", tmp_dir);
    let _ = fs::write(&tmp_input, &config_content);
    let _ = fs::write(&tmp_output, &themed);

    if final_output.is_some() {
        eprintln!("saving config at {} to {}", resolved_config, tmp_input);
    }

    let validation_path = &tmp_output;
    let output = Command::new("i3")
        .arg("-C")
        .arg("-c")
        .arg(validation_path)
        .output();

    match output {
        Ok(out) => {
            if !out.status.success() {
                eprintln!("Could not validate config.\nUse `i3 -C -c {}` to see validation errors.", resolved_config);
                exit(1);
