fn load_theme(name: &str) -> Result<theme::ThemeData, String> {
    let path = Path::new(name);
    if name.contains('/') || path.exists() {
        let content = fs::read_to_string(name).map_err(|e| e.to_string())?;
        let data: theme::ThemeData = serde_yaml::from_str(&content).map_err(|e| e.to_string())?;
        return Ok(data);
    }
    if let Some(t) = themes::get_theme(name) {
        let mut theme_data = theme::ThemeData {
            meta: theme::Meta { description: t.description.to_string() },
            colors: HashMap::new(),
            window_colors: HashMap::new(),
            bar_colors: theme::BarColors {
                background: String::new(),
                statusline: String::new(),
                separator: String::new(),
                focused_workspace: None,
                active_workspace: None,
                inactive_workspace: None,
                urgent_workspace: None,
            },
        };
        let mut name_counter: HashMap<String, usize> = HashMap::new();
        for (cls, vals) in &t.window {
            let mut names = Vec::new();
            for hex in vals {
                let mut found: Option<String> = None;
                for (n, h) in &theme_data.colors {
                    if h.eq_ignore_ascii_case(hex) {
                        found = Some(n.clone());
                        break;
                    }
                }
                let name = if let Some(n) = found {
                    n
                } else {
                    let base = color::hex_to_name(hex);
                    let cnt = name_counter.entry(base.clone()).or_insert(0);
                    let n = if *cnt == 0 { base.clone() } else { format!("{}-{}", base, cnt) };
                    *cnt += 1;
                    theme_data.colors.insert(n.clone(), hex.to_string());
                    n
                };
                names.push(name);
            }
            let wc = theme::WindowColors {
                border: names[0].clone(),
                background: names[1].clone(),
                text: names[2].clone(),
                indicator: names[3].clone(),
            };
            theme_data.window_colors.insert(cls.to_string(), wc);
        }
        for (key, vals) in &t.bar {
            if vals.len() == 1 {
                let hex = &vals[0];
                let mut found: Option<String> = None;
                for (n, h) in &theme_data.colors {
                    if h.eq_ignore_ascii_case(hex) {
                        found = Some(n.clone());
                        break;
                    }
                }
                let name = if let Some(n) = found {
                    n
                } else {
                    let base = color::hex_to_name(hex);
                    let cnt = name_counter.entry(base.clone()).or_insert(0);
                    let n = if *cnt == 0 { base.clone() } else { format!("{}-{}", base, cnt) };
                    *cnt += 1;
                    theme_data.colors.insert(n.clone(), hex.to_string());
                    n
                };
                match key.as_ref() {
                    "background" => theme_data.bar_colors.background = name,
                    "statusline" => theme_data.bar_colors.statusline = name,
                    "separator" => theme_data.bar_colors.separator = name,
                    _ => {}
                }
            } else {
                let mut names = Vec::new();
                for hex in vals {
                    let mut found: Option<String> = None;
                    for (n, h) in &theme_data.colors {
                        if h.eq_ignore_ascii_case(hex) {
                            found = Some(n.clone());
                            break;
                        }
                    }
                    let name = if let Some(n) = found {
                        n
                    } else {
                        let base = color::hex_to_name(hex);
                        let cnt = name_counter.entry(base.clone()).or_insert(0);
                        let n = if *cnt == 0 { base.clone() } else { format!("{}-{}", base, cnt) };
                        *cnt += 1;
                        theme_data.colors.insert(n.clone(), hex.to_string());
                        n
                    };
                    names.push(name);
                }
                let wc = theme::BarWorkspaceColors {
                    border: names[0].clone(),
                    background: names[1].clone(),
                    text: names[2].clone(),
                };
                match key.as_ref() {
                    "focused_workspace" => theme_data.bar_colors.focused_workspace = Some(wc),
                    "active_workspace" => theme_data.bar_colors.active_workspace = Some(wc),
                    "inactive_workspace" => theme_data.bar_colors.inactive_workspace = Some(wc),
                    "urgent_workspace" => theme_data.bar_colors.urgent_workspace = Some(wc),
                    _ => {}
                }
            }
        }
        Ok(theme_data)
    } else {
        Err("No such file or directory".to_string())
    }
}

fn handle_to_theme(path: &str, _output: Option<&str>) {
    let config_path = if path.is_empty() {
        match find_default_config() {
