            if !out.status.success() {
                eprintln!("Could not validate config.\nUse `i3 -C -c {}` to see validation errors.", config_path);
                exit(1);
            }
        }
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) No such file or directory (os error 2)", config_path);
                exit(1);
            } else {
                eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) No such file or directory (os error 2)", config_path);
                exit(1);
            }
        }
    }
    let theme_data = theme::generate_theme_from_content(&content, &config_path);
    let yaml = theme::theme_to_yaml(&theme_data);
    println!("{}", yaml);
}
