use std::collections::HashMap;
use regex::Regex;
use crate::color;

#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct ThemeData {
    pub meta: Meta,
    pub colors: HashMap<String, String>,
    #[serde(skip)]
    pub colors_order: Vec<String>,
    pub window_colors: HashMap<String, WindowColors>,
    pub bar_colors: BarColors,
}

#[derive(Debug, serde::Serialize, serde::Deserialize)]
pub struct Meta {
    pub description: String,
}

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
pub struct WindowColors {
    pub border: String,
    pub background: String,
    pub text: String,
    pub indicator: String,
}

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
pub struct BarColors {
    pub background: String,
    pub statusline: String,
    pub separator: String,
    pub focused_workspace: Option<BarWorkspaceColors>,
    pub active_workspace: Option<BarWorkspaceColors>,
    pub inactive_workspace: Option<BarWorkspaceColors>,
    pub urgent_workspace: Option<BarWorkspaceColors>,
}

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
pub struct BarWorkspaceColors {
    pub border: String,
    pub background: String,
    pub text: String,
}

pub fn generate_theme_from_content(content: &str, _path: &str) -> ThemeData {
    let mut colors: HashMap<String, String> = HashMap::new();
    let mut colors_order: Vec<String> = Vec::new();
    let mut name_counter: HashMap<String, usize> = HashMap::new();
    let mut window_colors: HashMap<String, WindowColors> = HashMap::new();
    let mut bar_background: Option<String> = None;
    let mut bar_statusline: Option<String> = None;
    let mut bar_separator: Option<String> = None;
    let mut bar_focused: Option<BarWorkspaceColors> = None;
    let mut bar_urgent: Option<BarWorkspaceColors> = None;

    let mut get_name = |hex: &str, colors: &mut HashMap<String, String>, order: &mut Vec<String>, counter: &mut HashMap<String, usize>| -> String {
        let hex_upper = color::normalize_hex(hex);
        for (n, h) in colors.iter() {
            if h.eq_ignore_ascii_case(&hex_upper) {
                return n.clone();
            }
        }
        let base = color::hex_to_name(&hex_upper);
        let cnt = counter.entry(base.clone()).or_insert(0);
        let name = if *cnt == 0 {
            base.clone()
        } else {
            format!("{}-{}", base, cnt)
        };
        *cnt += 1;
        colors.insert(name.clone(), hex_upper);
        order.push(name.clone());
        name
    };

    let re_bar_block = Regex::new(r"bar\s*\{\s*colors\s*\{([^}]*)\}").unwrap();
    let re_bg = Regex::new(r"background\s+([#\w]+)").unwrap();
    let re_status = Regex::new(r"statusline\s+([#\w]+)").unwrap();
    let re_sep = Regex::new(r"separator\s+([#\w]+)").unwrap();
    let re_focused = Regex::new(r"focused_workspace\s+([#\w]+)\s+([#\w]+)\s+([#\w]+)").unwrap();
    let re_urgent = Regex::new(r"urgent_workspace\s+([#\w]+)\s+([#\w]+)\s+([#\w]+)").unwrap();
    let re_inactive = Regex::new(r"inactive_workspace\s+([#\w]+)\s+([#\w]+)\s+([#\w]+)").unwrap();

    for cap in re_bar_block.captures_iter(content) {
        let block = cap.get(1).unwrap().as_str();
        if let Some(m) = re_sep.captures(block) {
            let hex = m.get(1).unwrap().as_str();
            let name = get_name(hex, &mut colors, &mut colors_order, &mut name_counter);
            bar_separator = Some(name);
        }
        if let Some(m) = re_bg.captures(block) {
            let hex = m.get(1).unwrap().as_str();
            let name = get_name(hex, &mut colors, &mut colors_order, &mut name_counter);
            bar_background = Some(name);
        }
        if let Some(m) = re_status.captures(block) {
            let hex = m.get(1).unwrap().as_str();
            let name = get_name(hex, &mut colors, &mut colors_order, &mut name_counter);
            bar_statusline = Some(name);
        }
        if let Some(m) = re_focused.captures(block) {
            let b = m.get(1).unwrap().as_str();
            let bg = m.get(2).unwrap().as_str();
            let txt = m.get(3).unwrap().as_str();
            let bn = get_name(b, &mut colors, &mut colors_order, &mut name_counter);
            let bgn = get_name(bg, &mut colors, &mut colors_order, &mut name_counter);
            let tn = get_name(txt, &mut colors, &mut colors_order, &mut name_counter);
            bar_focused = Some(BarWorkspaceColors { border: bn, background: bgn, text: tn });
        }
        if let Some(m) = re_inactive.captures(block) {
            let b = m.get(1).unwrap().as_str();
            let bg = m.get(2).unwrap().as_str();
            let txt = m.get(3).unwrap().as_str();
            let _ = get_name(b, &mut colors, &mut colors_order, &mut name_counter);
            let _ = get_name(bg, &mut colors, &mut colors_order, &mut name_counter);
            let _ = get_name(txt, &mut colors, &mut colors_order, &mut name_counter);
        }
        if let Some(m) = re_urgent.captures(block) {
            let b = m.get(1).unwrap().as_str();
            let bg = m.get(2).unwrap().as_str();
            let txt = m.get(3).unwrap().as_str();
            let bn = get_name(b, &mut colors, &mut colors_order, &mut name_counter);
            let bgn = get_name(bg, &mut colors, &mut colors_order, &mut name_counter);
            let tn = get_name(txt, &mut colors, &mut colors_order, &mut name_counter);
            bar_urgent = Some(BarWorkspaceColors { border: bn, background: bgn, text: tn });
        }
    }

    let re_window = Regex::new(r"client\.(focused_inactive|focused|unfocused|urgent)\s+([#\w]+)\s+([#\w]+)\s+([#\w]+)(?:\s+([#\w]+))?").unwrap();
    for cap in re_window.captures_iter(content) {
        let cls = cap.get(1).unwrap().as_str();
        let border = cap.get(2).unwrap().as_str();
        let background = cap.get(3).unwrap().as_str();
        let text = cap.get(4).unwrap().as_str();
        let indicator_opt = cap.get(5).map(|m| m.as_str());
        let border_name = get_name(border, &mut colors, &mut colors_order, &mut name_counter);
        let bg_name = get_name(background, &mut colors, &mut colors_order, &mut name_counter);
        let text_name = get_name(text, &mut colors, &mut colors_order, &mut name_counter);
        if let Some(ind) = indicator_opt {
            let ind_name = get_name(ind, &mut colors, &mut colors_order, &mut name_counter);
            let wc = WindowColors {
                border: border_name,
                background: bg_name,
                text: text_name,
                indicator: ind_name,
            };
            window_colors.insert(cls.to_string(), wc);
        } else {
            let wc = WindowColors {
                border: border_name,
                background: bg_name,
                text: text_name,
                indicator: String::new(),
            };
            window_colors.insert(cls.to_string(), wc);
        }
    }

    let bar_colors = BarColors {
        background: bar_background.unwrap_or_default(),
        statusline: bar_statusline.unwrap_or_default(),
        separator: bar_separator.unwrap_or_default(),
        focused_workspace: bar_focused,
        active_workspace: None,
        inactive_workspace: None,
        urgent_workspace: bar_urgent,
    };

    ThemeData {
        meta: Meta { description: "AUTOMATICALLY GENERATED THEME".to_string() },
        colors,
        colors_order,
        window_colors,
        bar_colors,
    }
}

pub fn theme_to_yaml(theme: &ThemeData) -> String {
    let mut out = String::new();
    out.push_str("---\n");
    out.push_str("meta:\n");
    out.push_str(&format!("  description: {}\n", theme.meta.description));
    out.push_str("colors:\n");
    if theme.colors.is_empty() {
        out.push_str("  {}\n");
    } else {
        if !theme.colors_order.is_empty() {
            for k in &theme.colors_order {
                if let Some(v) = theme.colors.get(k) {
                    out.push_str(&format!("  {}: \"{}\"\n", k, v));
                }
            }
        } else {
            let mut keys: Vec<_> = theme.colors.keys().collect();
            keys.sort();
            for k in keys {
                let v = &theme.colors[k];
                out.push_str(&format!("  {}: \"{}\"\n", k, v));
            }
        }
    }
    out.push_str("window_colors:\n");
    if theme.window_colors.is_empty() {
        out.push_str("  {}\n");
    } else {
        let order = ["focused", "focused_inactive", "unfocused", "urgent"];
        for cls in &order {
            if let Some(wc) = theme.window_colors.get(*cls) {
                out.push_str(&format!("  {}:\n", cls));
                out.push_str(&format!("    border: {}\n", wc.border));
                out.push_str(&format!("    background: {}\n", wc.background));
                out.push_str(&format!("    text: {}\n", wc.text));
                if !wc.indicator.is_empty() {
                    out.push_str(&format!("    indicator: {}\n", wc.indicator));
                }
            }
        }
        for (cls, wc) in &theme.window_colors {
            if !order.contains(&cls.as_str()) {
                out.push_str(&format!("  {}:\n", cls));
                out.push_str(&format!("    border: {}\n", wc.border));
                out.push_str(&format!("    background: {}\n", wc.background));
                out.push_str(&format!("    text: {}\n", wc.text));
                if !wc.indicator.is_empty() {
                    out.push_str(&format!("    indicator: {}\n", wc.indicator));
                }
            }
        }
    }
    out.push_str("bar_colors:\n");
    let is_empty = theme.bar_colors.background.is_empty() && theme.bar_colors.statusline.is_empty() && theme.bar_colors.separator.is_empty() && theme.bar_colors.focused_workspace.is_none() && theme.bar_colors.urgent_workspace.is_none();
    if is_empty {
        out.push_str("  {}\n");
    } else {
        if !theme.bar_colors.background.is_empty() {
            out.push_str(&format!("  background: {}\n", theme.bar_colors.background));
        }
        if !theme.bar_colors.statusline.is_empty() {
            out.push_str(&format!("  statusline: {}\n", theme.bar_colors.statusline));
        }
        if !theme.bar_colors.separator.is_empty() {
            out.push_str(&format!("  separator: {}\n", theme.bar_colors.separator));
        }
        if let Some(fw) = &theme.bar_colors.focused_workspace {
            out.push_str("  focused_workspace:\n");
            out.push_str(&format!("    border: {}\n", fw.border));
            out.push_str(&format!("    background: {}\n", fw.background));
            out.push_str(&format!("    text: {}\n", fw.text));
        }
        if let Some(aw) = &theme.bar_colors.active_workspace {
            out.push_str("  active_workspace:\n");
            out.push_str(&format!("    border: {}\n", aw.border));
            out.push_str(&format!("    background: {}\n", aw.background));
            out.push_str(&format!("    text: {}\n", aw.text));
        }
        if let Some(iw) = &theme.bar_colors.inactive_workspace {
            out.push_str("  inactive_workspace:\n");
            out.push_str(&format!("    border: {}\n", iw.border));
            out.push_str(&format!("    background: {}\n", iw.background));
            out.push_str(&format!("    text: {}\n", iw.text));
        }
        if let Some(uw) = &theme.bar_colors.urgent_workspace {
            out.push_str("  urgent_workspace:\n");
            out.push_str(&format!("    border: {}\n", uw.border));
            out.push_str(&format!("    background: {}\n", uw.background));
            out.push_str(&format!("    text: {}\n", uw.text));
        }
    }
    out
}
